import {celebrateDay} from './celebration.js';
import {createGitHubSync,SNAPSHOT_URL,trainingSignature} from './github-sync.js';
import {attachRepSlider} from './reps.js';
import {attachStack} from './gestures.js';
import {DAYS,ROUTINES,initialState,remaining,currentEntry,navigate,completeEntry,archiveWeek,previousResult,validateState,migrateState,repRange,repInputValue,loadUnit,unitSuffix,weightText,toCSV} from './model.js';
import {openDB,readState,persist} from './storage.js';
const app=document.querySelector('#app'),modal=document.querySelector('#modal'),notice=document.querySelector('#notice');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const displayLabel=x=>String(x??'').replace(/^./,c=>c.toUpperCase());
const daySymbols={Push:'M4 20 20 4M4 4h16v16',Pull:'M20 4 4 20M4 4v16h16',Legs:'M4 12 8 4 16 20 20 12',Upper:'M4 12 12 4 20 12M4 20 12 12 20 20',Lower:'M4 4 12 12 20 4M4 12 12 20 20 12',Bonus:'M12 4 15 9 20 12 15 15 12 20 9 15 4 12 9 9Z',Complete:'M4 12 10 20 20 4'};
const dayIcon=name=>'<svg class="day-symbol" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="'+daySymbols[name]+'"/></svg>';
const effortIcons={more:'<path d="M12 19V5m-5 5 5-5 5 5"/>',right:'<path d="m5 12 4 4L19 6"/>',hard:'<path d="M12 5v14m-5-5 5 5 5-5"/>'};
const effortIcon=v=>'<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">'+effortIcons[v]+'</svg>';
const effortText={more:'Could do more',right:'Just right',hard:'Too hard'};
let overviewOpen=false,githubStatus='Not connected. Workouts are saved on this device.',githubRemote=null;
const github=createGitHubSync({getState:()=>state,notify:text=>{githubStatus=text;const el=document.querySelector('#github-status');if(el)el.textContent=text;}});
let state,queue=Promise.resolve(),failed=null,historyId=null,noticeTimer,changingWeek=false,disposeStack=()=>{};
function message(text,action,label='Retry'){clearTimeout(noticeTimer);notice.textContent=text;if(action){const b=document.createElement('button');b.textContent=label;b.onclick=action;notice.append(b);}else noticeTimer=setTimeout(()=>notice.replaceChildren(),4500);}
function commit(edit,{refresh=true}={}){const task=queue.then(async()=>{if(failed)throw new Error('Retry the unsaved change first.');const next=structuredClone(state);edit(next);next.revision=state.revision+1;try{await persist(next,state.revision);}catch(error){failed={edit,refresh:true};render();message(error.message,async()=>{const f=failed;failed=null;notice.replaceChildren();await commit(f.edit,{refresh:f.refresh}).catch(()=>{});});throw error;}const changed=trainingSignature(state)!==trainingSignature(next);state=next;if(changed)github.schedule();if(refresh)render();return state;});queue=task.catch(()=>{});return task;}
const change=(fn,opts)=>commit(fn,opts).catch(e=>{if(!failed)message(e.message);});
const entryAt=(s,day,id)=>s.active.days[day].entries.find(e=>e.id===id);
function go(page,day=null){overviewOpen=false;return change(s=>{s.view={page,day}});}
function bind(action,fn){app.querySelectorAll(`[data-action="${action}"]`).forEach(b=>b.addEventListener('click',()=>fn(b)));}
function back(){return '<button class="back" data-action="home">← <span>Training</span></button>';}
function render(){disposeStack();disposeStack=()=>{};const focus=document.activeElement?.id;const page=state.view.page;app.dataset.page=page;app.innerHTML=page==='home'?home():page==='day'?dayView():page==='review'?review():page==='history'?history():backup();bindUI();if(focus)document.getElementById(focus)?.focus({preventScroll:true});}
function home(){return `<header><div><h1>Training</h1><p>Week ${state.active.number}</p></div><button class="outline" data-action="new-week">↻ &nbsp; New week</button></header><div class="home-grid">${DAYS.map(d=>{const ses=state.active.days[d],done=ses.entries.length-remaining(ses).length;return `<button class="tile ${done===ses.entries.length?'complete':''}" data-action="day" data-day="${d}" aria-label="${d}, ${done} of ${ses.entries.length} done"><span>${dayIcon(done===ses.entries.length?'Complete':d)}</span><div class="tile-bottom"><h2>${d}</h2>${done?`<small>${done}/${ses.entries.length}</small>`:''}</div></button>`}).join('')}<button class="tile bonus ${state.active.bonus?'complete':''}" data-action="bonus" aria-pressed="${state.active.bonus}" aria-label="${state.active.bonus?'Undo Bonus completion':'Complete Bonus'}"><span>${dayIcon(state.active.bonus?'Complete':'Bonus')}</span><h2>Bonus</h2></button></div><footer class="footer"><button class="text-button" data-action="history">History${state.archives.length?' · '+state.archives.length:''}</button><button class="text-button" data-action="backup">Backup & settings</button></footer>`;}
function previousMarkup(day,e){const p=previousResult(state,day,e);if(!p)return '<div class="previous">No previous result</div>';return '<div class="previous">Last: <strong>'+esc(weightText(p))+(p.reps===null?'':' × '+p.reps)+'</strong></div>';}
function repsMarkup(e){const sliderId='reps-'+e.id;const range=repRange(e),value=repInputValue(e),percent=(value-range.min)/(range.max-range.min)*100;return `<div class="field-label"><label for="${esc(sliderId)}">Reps Achieved</label><output class="rep-output rep-number" for="${esc(sliderId)}">${e.completed?(e.reps??'—'):value}</output></div><div class="rep-control" style="--rep-position:${percent}%"><div class="rep-rail" aria-hidden="true"><div class="rep-fill"></div><div class="rep-ticks">${range.values.map(()=>'<i></i>').join('')}</div><div class="rep-thumb"></div></div><input class="range" id="${esc(sliderId)}" type="range" min="${range.min}" max="${range.max}" step="1" value="${value}" aria-label="Reps achieved"></div><div class="range-labels rep-stops" aria-hidden="true">${range.values.map(n=>'<span>'+n+'</span>').join('')}</div>`;}
function cardMarkup(day,e){return `<article class="exercise-card ${e.completed?'is-complete':''}" data-entry="${esc(e.id)}" aria-label="${esc(e.variant||e.name)}${e.completed?', completed':''}" tabindex="0"><h2>${esc(e.variant||e.name)}</h2><div class="chips"><span class="chip">${e.sets} sets</span><span class="chip">${esc(e.target)} reps</span></div><div class="weight-label"><span>Working Weight</span><button class="text-button" style="padding:0;min-height:32px" data-action="equipment" aria-label="Weight Set-up">Weight Set-up</button></div><div class="weight-stepper"><button class="step" data-action="minus" aria-label="Decrease working weight"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M5 12h14"/></svg></button><div class="weight-value"><span>${e.precision==='estimated'&&e.weight!==null?'≈ ':''}${e.weight===null?'—':esc(e.weight)}</span> <small>${esc(unitSuffix(e))}</small></div><button class="step" data-action="plus" aria-label="Increase working weight"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M5 12h14M12 5v14"/></svg></button></div><div class="unit">${esc(displayLabel(e.unit))}</div>${previousMarkup(day,e)}${repsMarkup(e)}<p class="effort-label">How did it feel?</p><div class="effort">${[['more','', 'Could do more'],['right','','Just right'],['hard','','Too hard']].map(([v,icon,t])=>`<button data-action="effort" data-effort="${v}" aria-pressed="${e.effort===v}"><span aria-hidden="true">${effortIcon(v)}</span>${t}</button>`).join('')}</div><button class="primary done-button" data-action="done" aria-label="${e.completed?'Undo completion':'Done'}">${e.completed?'Completed · Undo':'Done &nbsp; ✓'}</button></article>`;}
function dayView(){const day=state.view.day,ses=state.active.days[day],r=remaining(ses);
return `<header class="workout-nav">${back()}<h1>${day}</h1><button id="overview-toggle" class="overview-toggle" data-action="overview" aria-label="${overviewOpen?'Close overview':'All exercises'}" aria-expanded="${overviewOpen}" title="${overviewOpen?'Close overview':'All exercises'}"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">${overviewOpen?'<path d="m6 6 12 12M6 18 18 6"/>':'<rect x="4" y="4" width="6" height="6" rx="1.5"/><rect x="14" y="4" width="6" height="6" rx="1.5"/><rect x="4" y="14" width="6" height="6" rx="1.5"/><rect x="14" y="14" width="6" height="6" rx="1.5"/>'}</svg></button></header><div class="workout-status"><span id="remaining-count">${r.length} of ${ses.entries.length} remaining</span><span>Week ${state.active.number}</span></div><div class="progress" role="group" aria-label="${ses.entries.length-r.length} of ${ses.entries.length} exercises done">${ses.entries.map(x=>`<button class="${x.completed?'done':''}" data-action="select-exercise" data-id="${esc(x.id)}" data-progress="${esc(x.id)}" aria-label="${esc(x.variant||x.name)}, ${x.completed?'completed':'not completed'}"></button>`).join('')}</div>${overviewOpen?overviewMarkup(ses):`<div class="card-stack" role="region" aria-label="Workout cards">${ses.entries.map(e=>cardMarkup(day,e)).join('')}</div>`}`;}
function overviewMarkup(ses){return '<div class="exercise-overview" role="region" aria-label="All exercises">'+ses.entries.map(e=>'<button class="mini-card '+(e.completed?'is-complete':'')+'" data-action="select-exercise" data-id="'+esc(e.id)+'" aria-label="'+esc(e.variant||e.name)+(e.completed?', completed':', not completed')+'">'+esc(e.variant||e.name)+'</button>').join('')+'</div>';}
function entrySummary(e){return [e.weight!==null?weightText(e):null,e.reps!==null?e.reps+' reps':null,e.effort?effortText[e.effort]:null].filter(Boolean).join(' · ')||'Completed without a log';}
function review(){const day=state.view.day,done=state.active.days[day].entries.filter(e=>e.completed);return `${back()}<header><h1>${day} results</h1></header>${done.length?done.map(e=>`<div class="row"><div><strong>${esc(e.variant||e.name)}</strong><p>${esc(entrySummary(e))}</p></div><button class="outline" data-action="undo" data-id="${e.id}">Undo</button></div>`).join(''):'<p>No completed exercises yet.</p>'}<button class="primary" style="margin-top:28px" data-action="return-day">Back to ${day}</button>`;}
function history(){const w=state.archives.find(x=>x.id===historyId)||state.archives.at(-1);return `${back()}<header><h1>History</h1></header>${w?`<label for="history-week" class="visually-hidden">Archived week</label><select id="history-week" class="history-select">${[...state.archives].reverse().map(x=>`<option value="${esc(x.id)}" ${x.id===w.id?'selected':''}>Week ${x.number}</option>`).join('')}</select>${DAYS.map(d=>`<details class="panel"><summary>${d} · ${w.days[d].entries.filter(e=>e.completed).length}/${w.days[d].entries.length} done</summary>${w.days[d].entries.map(e=>`<div class="row"><div><strong>${esc(e.variant||e.name)}</strong><p>${e.completed?'✓ Done':'Unfinished'} · ${esc(entrySummary(e).replace('Completed without a log','No log'))}</p></div></div>`).join('')}</details>`).join('')}<p>Bonus: ${w.bonus?'complete':'not completed'}</p>`:'<p>Your archived weeks will appear here after you choose New week.</p>'}<details class="panel"><summary>Reported & historical results</summary>${state.seed.map(e=>`<div class="row"><div><strong>${esc(e.name||ROUTINES[e.day].find(x=>x.id===e.id)?.name||e.id)}</strong><p>${esc(weightText(e))}${e.reps===null?'':' × '+e.reps+' reps'}<br>${e.sets} sets${e.sets_source==='routine_inferred'?' (from routine)':''} · ${e.day}<br>${e.date?esc(e.date.slice(0,10)):'Date not recorded'}</p></div></div>`).join('')}</details>`;}
function backup(){return `${back()}<header><h1>Backup & settings</h1></header><section class="panel"><h2>Your training data</h2><p>Saved on this device for offline use. Connect GitHub below to also save your workouts to your repository.</p><div class="actions"><button class="primary" data-action="export">Export backup</button><button class="outline" data-action="csv">Export CSV</button></div><button class="text-button" data-action="import">Restore a backup</button><input type="file" accept=".json,application/json" id="import-file" hidden><p>JSON restores your full week, drafts and history. CSV is for viewing results in a spreadsheet.</p></section>${githubPanel()}<section class="panel"><h2>On your iPhone</h2><p id="app-version">Version 15</p><p>Open this app in Safari, then Share → Add to Home Screen. Open it once while online to prepare it for offline use.</p><p id="offline-status">${navigator.serviceWorker?.controller?'Offline app ready.':'Offline setup will finish after the first online visit.'}</p></section><section class="panel"><h2>Weight Set-up</h2><p>Choose kg, lb, or Unknown and set your equipment’s increment. Unknown values appear without a unit. Your choices carry into the next week.</p></section>`;}
function githubPanel(){return '<section class="panel"><h2>GitHub storage</h2><p>Workout history is saved publicly in SamHMews/PPLUL, at data/workouts.json. Offline changes upload while the app is open and connected.</p><p id="github-status" role="status">'+esc(githubStatus)+'</p><label for="github-token">GitHub token</label><input id="github-token" type="password" autocomplete="off" spellcheck="false" placeholder="Enter token to connect"><p>Your connection is remembered on this device across sessions. Disconnect removes the saved token. Tokens are never included in workout backups.</p><div class="actions"><button class="primary" data-action="github-connect">Connect GitHub</button><button class="outline" data-action="github-save">Save now</button></div><button class="text-button" data-action="github-disconnect">Disconnect</button>'+(githubRemote?'<div class="actions"><button class="outline" data-action="github-restore">Use GitHub copy</button><button class="outline" data-action="github-replace">Use this device’s copy</button></div>':'')+'<p><a href="https://github.com/settings/personal-access-tokens/new" target="_blank" rel="noopener noreferrer">Create a fine-grained token</a> for PPLUL only, with Contents: Read and write. <a href="'+SNAPSHOT_URL+'" target="_blank" rel="noopener noreferrer">View saved history</a></p></section>';}
async function connectGitHub(token){try{const remote=await github.connect(token);githubRemote=remote?migrateState(remote):null;if(remote)message('GitHub and this device have different copies. Choose one in Backup & settings.');if(state.view.page==='backup')render();}catch(e){githubStatus=e.message;message(e.message);if(state.view.page==='backup')render();}}
function bindGitHub(){
 bind('github-connect',()=>{const input=app.querySelector('#github-token'),token=input.value;input.value='';connectGitHub(token);});
 bind('github-save',async()=>{await queue;if(github.hasToken()){await connectGitHub();}else{githubStatus='Connect GitHub on this device first. Your workouts are still saved here.';app.querySelector('#github-status').textContent=githubStatus;message(githubStatus);app.querySelector('#github-token').focus();}});
 bind('github-disconnect',()=>{try{github.disconnect();githubRemote=null;render();}catch(e){message(e.message);}});
 bind('github-restore',()=>confirmDialog('Use GitHub history?','Replace this device’s workouts with the GitHub copy. Export a backup first if you want to keep both.','Use GitHub copy',async()=>{await commit(s=>{const revision=s.revision;Object.assign(s,structuredClone(githubRemote),{revision,view:{page:'backup',day:null}});});await github.chooseRemote();githubRemote=null;render();}));
 bind('github-replace',()=>confirmDialog('Use this device’s history?','Replace the current GitHub file with this device’s workouts. Earlier versions remain in GitHub commit history.','Save device copy',async()=>{await queue;await github.chooseLocal();githubRemote=null;render();}));
}
function showDialog(html){modal.innerHTML=html;modal.showModal();modal.querySelector('[data-close]')?.addEventListener('click',()=>modal.close());}
function confirmDialog(title,body,label,action){showDialog(`<h2>${title}</h2><p>${body}</p><div class="actions"><button class="outline" data-close>Cancel</button><button class="primary" id="confirm-action">${label}</button></div>`);modal.querySelector('#confirm-action').onclick=async ev=>{ev.target.disabled=true;try{await action();modal.close();}catch(e){ev.target.disabled=false;if(!failed)message(e.message);}};}
function equipment(day,id,after){
 const e=entryAt(state,day,id),types=['total weight','per dumbbell','machine weight','added weight','assistance weight','bodyweight'];
 showDialog(`<h2>Weight Set-up</h2><p>${esc(e.variant||e.name)}</p><label>Unit<select id="load-unit">${[['kg','kg'],['lb','lb'],['unknown','Unknown']].map(([v,t])=>'<option value="'+v+'" '+(loadUnit(e)===v?'selected':'')+'>'+t+'</option>').join('')}</select></label><label>Weight Means<select id="unit">${e.unit==='choose weight type'?'<option value="">Choose a Weight Type</option>':''}${types.map(u=>'<option '+(u===e.unit?'selected':'')+' value="'+u+'">'+u.replace(/\b\w/g,c=>c.toUpperCase())+'</option>').join('')}</select></label><label>Increment<select id="increment"><option value="">Choose an Increment</option>${[.5,1,1.25,2,2.5,5,10].map(n=>'<option value="'+n+'" '+(n===e.increment?'selected':'')+'>'+n+'</option>').join('')}<option value="custom" ${e.increment&&![.5,1,1.25,2,2.5,5,10].includes(e.increment)?'selected':''}>Other Increment</option></select></label><label id="custom-label" hidden>Custom Increment<input id="custom-increment" type="number" min="0.01" max="100" step="0.01" value="${e.increment??''}"></label><div class="actions"><button class="outline" data-close>Cancel</button><button class="primary" id="save-equipment">Use Settings</button></div>`);
 const showCustom=()=>{modal.querySelector('#custom-label').hidden=modal.querySelector('#increment').value!=='custom';};modal.querySelector('#increment').onchange=showCustom;showCustom();
 modal.querySelector('#save-equipment').onclick=async ev=>{const unit=modal.querySelector('#unit').value,measurement=modal.querySelector('#load-unit').value,raw=modal.querySelector('#increment').value,increment=raw==='custom'?Number(modal.querySelector('#custom-increment').value):Number(raw);if(!unit||!Number.isFinite(increment)||increment<=0||increment>100){message('Choose a weight type and a valid increment.');return;}ev.target.disabled=true;await commit(s=>{const x=entryAt(s,day,id);if(x.unit!==unit||loadUnit(x)!==measurement){x.weight=null;x.precision='exact';}x.unit=unit;x.loadUnit=measurement;x.increment=increment;s.settings[day+':'+id]={unit,increment,loadUnit:measurement};}).then(()=>{modal.close();after?.();}).catch(()=>{ev.target.disabled=false;});};
}
function adjustWeight(day,id,delta){const e=entryAt(state,day,id);if(e.completed)return;if(e.increment&&e.unit!=='choose weight type'&&(e.weight===null||delta>0||e.weight>0)){try{navigator.vibrate?.(8);}catch{}}if(!e.increment||e.unit==='choose weight type'){equipment(day,id,()=>adjustWeight(day,id,delta));return;}change(s=>{const x=entryAt(s,day,id);if(x.completed)return;const p=previousResult(s,day,x);if(x.weight===null&&p?.weight!=null){x.weight=p.weight;x.precision=p.precision;}else {x.weight=Math.max(0,Math.round(((x.weight??0)+delta*x.increment)*100)/100);}});}
function download(name,content,type){const u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),30000);}
async function exportData(csv=false){await queue;download(`training-${new Date().toISOString().slice(0,10)}.${csv?'csv':'json'}`,csv?toCSV(state):JSON.stringify(state,null,2),csv?'text/csv':'application/json');}
function bindUI(){bindGitHub();bind('home',()=>go('home'));bind('day',b=>go('day',b.dataset.day));bind('bonus',()=>change(s=>{s.active.bonus=!s.active.bonus}));bind('history',()=>go('history'));bind('backup',()=>go('backup'));bind('new-week',()=>{if(changingWeek)return;const weekId=state.active.id;confirmDialog('Start a new week?',`Archive Week ${state.active.number}, including unfinished exercises and drafts, and start Week ${state.active.number+1}. All history is kept.`,'Start new week',async()=>{if(changingWeek)return;changingWeek=true;try{await commit(s=>{if(s.active.id!==weekId)throw new Error('This week has already been archived.');archiveWeek(s);});}finally{changingWeek=false;}});});bind('export',()=>exportData());bind('csv',()=>exportData(true));bind('import',()=>app.querySelector('#import-file').click());const file=app.querySelector('#import-file');if(file)file.onchange=async()=>{try{const f=file.files[0];if(!f)return;if(f.size>20*1024*1024)throw new Error('This file is too large to be a Training backup.');const imported=migrateState(JSON.parse(await f.text()));confirmDialog('Restore this backup?',`Replace the data on this device with Week ${imported.active.number} and ${imported.archives.length} archived weeks. Export your current backup first if you want to keep it.`,'Restore backup',()=>commit(s=>{const revision=s.revision;Object.assign(s,structuredClone(imported),{revision,view:{page:'home',day:null}});}));}catch(e){message(e.message||'Could not read that backup.');}};const hw=app.querySelector('#history-week');if(hw)hw.onchange=()=>{historyId=hw.value;render()};if(!state.view.day)return;
const day=state.view.day,ses=state.active.days[day],e=currentEntry(ses),id=e?.id;bind('review',()=>go('review',day));bind('return-day',()=>go('day',day));bind('undo',b=>change(s=>{const x=entryAt(s,day,b.dataset.id);x.completed=false;x.completedAt=null;s.active.days[day].current=x.id;}));if(state.view.page!=='day'||!e)return;
bind('overview',async()=>{await queue;overviewOpen=!overviewOpen;render();app.querySelector('#overview-toggle').focus({preventScroll:true});});
bind('select-exercise',async b=>{try{await commit(s=>{s.active.days[day].current=b.dataset.id;},{refresh:false});overviewOpen=false;render();app.querySelector('.is-front').focus({preventScroll:true});}catch{}});
if(overviewOpen)return;
const stack=app.querySelector('.card-stack');
for(const card of stack.querySelectorAll('.exercise-card'))bindCard(card,day);
disposeStack=attachStack(stack,ses.current,async nextId=>{
 await commit(s=>{s.active.days[day].current=nextId;},{refresh:false});
});
}
function updateCardCompletion(card,e,day){
 card.classList.toggle('is-complete',e.completed);
 card.setAttribute('aria-label',(e.variant||e.name)+(e.completed?', completed':''));
 for(const input of card.querySelectorAll('button,input'))if(input.dataset.action!=='done')input.disabled=e.completed;
 const done=card.querySelector('[data-action=done]');done.innerHTML=e.completed?'Completed · Undo':'Done &nbsp; ✓';done.setAttribute('aria-label',e.completed?'Undo completion':'Done');done.disabled=false;
 const ses=state.active.days[day];app.querySelector('#remaining-count').textContent=remaining(ses).length+' of '+ses.entries.length+' remaining';
 const progress=app.querySelector('.progress');progress.setAttribute('aria-label',(ses.entries.length-remaining(ses).length)+' of '+ses.entries.length+' exercises done');
 for(const el of progress.children){const entry=entryAt(state,day,el.dataset.progress);el.classList.toggle('done',entry.completed);el.setAttribute('aria-label',(entry.variant||entry.name)+', '+(entry.completed?'completed':'not completed'));}
 card.querySelector('output').textContent=e.completed?(e.reps??'—'):repInputValue(e);
}
function bindCard(card,day){
 const id=card.dataset.entry,bind=(action,fn)=>card.querySelectorAll('[data-action="'+action+'"]').forEach(b=>b.addEventListener('click',()=>fn(b)));
 bind('plus',()=>adjustWeight(day,id,1));bind('minus',()=>adjustWeight(day,id,-1));bind('equipment',()=>equipment(day,id));
 bind('effort',b=>change(s=>{const x=entryAt(s,day,id);if(!x.completed)x.effort=x.effort===b.dataset.effort?null:b.dataset.effort;}));
 bind('done',async b=>{if(b.disabled)return;b.disabled=true;let finalCompletion=false;const weekId=state.active.id;try{await commit(s=>{const x=entryAt(s,day,id);if(x.completed){x.completed=false;x.completedAt=null;}else {finalCompletion=remaining(s.active.days[day]).length===1;completeEntry(s.active.days[day],id);}},{refresh:false});if(card.isConnected){updateCardCompletion(card,entryAt(state,day,id),day);if(finalCompletion){await celebrateDay(app);if(state.active.id===weekId&&state.view.page==='day'&&state.view.day===day)await go('home');}}}catch{if(card.isConnected)b.disabled=false;}});
 const slider=card.querySelector('input[type=range]');attachRepSlider(slider,value=>change(s=>{const x=entryAt(s,day,id);if(!x.completed)x.reps=value;},{refresh:false}));
 updateCardCompletion(card,entryAt(state,day,id),day);
}

async function init(){try{await openDB();const saved=await readState();if(saved){state=migrateState(saved);if(JSON.stringify(state)!==JSON.stringify(saved)){state.revision=saved.revision+1;await persist(state,saved.revision);}}else{state=initialState();state.revision=1;await persist(state,0);}if(state.view.page==='day'&&!DAYS.includes(state.view.day))state.view={page:'home',day:null};render();navigator.storage?.persist?.().catch(()=>{});if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(reg=>{const offer=()=>{if(navigator.serviceWorker.controller&&reg.waiting)message('An app update is ready.',async()=>{await queue;const waiting=reg.waiting;if(waiting){updateRequested=true;waiting.postMessage({type:'activate',clientWillReload:true});}} ,'Update');};offer();reg.addEventListener('updatefound',()=>reg.installing?.addEventListener('statechange',offer));return navigator.serviceWorker.ready;}).then(()=>{const n=document.querySelector('#offline-status');if(n)n.textContent='Offline app ready.';}).catch(()=>message('Offline setup could not finish. Keep this page open online and retry later.'));}registerTools();if(github.hasToken())connectGitHub();}catch(e){app.innerHTML=`<div class="center"><h1>Training</h1><p class="error">${esc(e.message||'Device storage is unavailable.')}</p><p>Your saved data has not been reset.</p><button class="primary" onclick="location.reload()">Try again</button></div>`;}}
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const tools=[{name:'read_training_week',description:'Read current training completion counts without changing data.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({week:state.active.number,bonus:state.active.bonus,days:DAYS.map(day=>({day,remaining:remaining(state.active.days[day]).length,total:state.active.days[day].entries.length}))})},{name:'open_training_day',description:'Navigate to a workout card deck. Does not complete or log any exercise.',inputSchema:{type:'object',properties:{day:{type:'string',enum:DAYS}},required:['day'],additionalProperties:false},execute:async input=>{if(!input||!DAYS.includes(input.day))throw new Error('Choose a valid training day.');await commit(s=>{s.view={page:'day',day:input.day};});return {day:input.day,exercise:currentEntry(state.active.days[input.day])?.name??null};}}];for(const t of tools){try{Promise.resolve(context.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}}}
window.addEventListener('online',()=>{if(state?.view.page==='day')render();if(github.hasToken())connectGitHub();});window.addEventListener('offline',()=>{if(state?.view.page==='day')render()});
let reloading=false,updateRequested=false; const hadController=Boolean(navigator.serviceWorker?.controller);
navigator.serviceWorker?.addEventListener('controllerchange',()=>{if((hadController||updateRequested)&&!reloading&&state){reloading=true;queue.finally(()=>location.reload());}});
init();
